}

/** POST /api/admin/product/update_attrs/:id — 行锁下更新库存价格。 */
export async function adminMobileProductUpdateAttrs(c: C) {
  privateNoStore(c);
  // Accommodate 500 SKU rows, including Unicode IDs and formatted JSON, while
